(()=>{'use strict';
const DB='abyss-deck-saves',STORE='saves',KEY='latest';
function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject();let q=indexedDB.open(DB,1);q.onupgradeneeded=()=>q.result.createObjectStore(STORE);q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error)})}
window.persistAbyssBackup=async raw=>{window.__abyssRunComplete=false;try{let db=await openDB(),tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(raw,KEY);await new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});db.close()}catch(e){}};
window.loadAbyssBackup=async()=>{try{let db=await openDB(),tx=db.transaction(STORE,'readonly'),q=tx.objectStore(STORE).get(KEY),raw=await new Promise((ok,no)=>{q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)});db.close();if(!raw)return null;let cutoff=Number(localStorage.getItem('abyssRunClearedAt')||0),saved=JSON.parse(raw)?.savedAt||0;return cutoff&&saved<=cutoff?null:raw}catch(e){return null}};
window.clearAbyssBackup=async()=>{try{let db=await openDB(),tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(KEY);await new Promise((ok,no)=>{tx.oncomplete=ok;tx.onerror=()=>no(tx.error)});db.close()}catch(e){}};
async function recover(){let button=document.getElementById('continueGame');if(!button)return;if(window.abyssCanContinue?.()){button.hidden=false;return}let raw=await window.loadAbyssBackup();if(raw){try{let s=JSON.parse(raw);if(Array.isArray(s.deck)&&s.deck.length){window.__abyssRecoveredSave=raw;button.hidden=false}}catch(e){}}}
function restoreInput(force=false){let g=window.getAbyssGame?.(),end=document.getElementById('endTurn');if(g?.cardBusy&&(force||!g.cardBusyAt||Date.now()-g.cardBusyAt>1400)){g.cardBusy=false;g.cardBusyAt=0}if(end&&g&&!g.turnBusy)end.disabled=false;document.querySelectorAll('#newGame,#continueGame,#titleSettingsMenu,.title-hub-grid button:not(:disabled),[data-hub-close],#titleBestiary,#titleCardCodex,#titleRelicCodex,#titleBgmGallery:not(:disabled),#titleCodex,#resetAllData,#resetCancel,#resetConfirm,#modifierClose,#strategyClose,#runModifierBadge,#mapHelpView,#mapHelpClose,#rewardGoldOption,#rewardCardOption,#rewardRelicOption,#rewardContinue,#rewardBack,#skipReward,.boss-relic-choice,.achievement-card:not(:disabled),.market-item:not(:disabled),.node.available,.choice,.card').forEach(b=>b.style.pointerEvents='auto')}
window.addEventListener('pageshow',()=>{recover();restoreInput(true);setTimeout(()=>{let g=window.getAbyssGame?.(),end=document.getElementById('endTurn'),battle=document.getElementById('battle');if(g&&battle?.classList.contains('on')&&g.turnBusy){g.turnBusy=false;if(end)end.disabled=false;window.abyssSave?.()}restoreInput(true)},2200)});
let touch=null;document.addEventListener('touchstart',e=>{let c=e.target.closest?.('#hand .card'),t=e.changedTouches?.[0];touch=c&&t?{c,x:t.clientX,y:t.clientY}:null},{capture:true,passive:true});document.addEventListener('touchend',e=>{let t=e.changedTouches?.[0];if(touch&&t&&e.target.closest?.('#hand .card')===touch.c&&Math.hypot(t.clientX-touch.x,t.clientY-touch.y)<36){e.preventDefault();restoreInput();if(window.playAbyssCardElement)window.playAbyssCardElement(touch.c);else touch.c.click()}touch=null},{capture:true,passive:false});document.addEventListener('pointerdown',()=>restoreInput(),{capture:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'){if(!window.__abyssRunComplete)window.abyssSave?.()}else restoreInput(true)});window.addEventListener('pagehide',()=>{if(!window.__abyssRunComplete)window.abyssSave?.()});recover();
function showTitle(completed=false){let g=window.getAbyssGame?.();if(!(completed&&g?.secretCleared))window.stopAbyssMusic?.();window.__abyssRunComplete=completed;if(!completed)window.abyssSave?.();else try{let now=Date.now();localStorage.setItem('abyssRunClearedAt',String(now));localStorage.removeItem('abyssDeck');localStorage.removeItem('abyssDeckBackup');window.__abyssRecoveredSave=null;window.clearAbyssBackup?.()}catch(e){}document.querySelectorAll('.modal.on').forEach(m=>m.classList.remove('on'));document.querySelectorAll('.screen').forEach(s=>s.classList.remove('on'));document.getElementById('title')?.classList.add('on');document.body.className='scene-title';let button=document.getElementById('suspendRun');if(button)button.textContent='⏸ 中断';window.refreshContinue?.();if(completed)setTimeout(()=>window.showAbyssShardGuide?.(),420)}
window.returnAbyssTitle=showTitle;
let suspend=document.createElement('button');suspend.id='suspendRun';suspend.className='suspend-run';suspend.textContent='⏸ 中断';suspend.setAttribute('aria-label','ゲームを保存して最初の画面へ戻る');suspend.onclick=()=>{let g=window.getAbyssGame?.();if(g?.turnBusy){suspend.textContent='保存待ち…';return setTimeout(()=>suspend.click(),260)}showTitle(false)};let mapButton=document.getElementById('mapHelpView');mapButton?.parentElement?mapButton.insertAdjacentElement('afterend',suspend):document.body.appendChild(suspend);document.getElementById('newGame')?.addEventListener('pointerdown',()=>{window.__abyssRunComplete=false},{capture:true});
})();
